---- SIH ---- 
SELECT 
    -- CPF: transforma vazio ou só zeros em NULL
    CASE 
        WHEN TRIM(A.NU_CPF_PCN) IS NULL 
             OR REGEXP_REPLACE(A.NU_CPF_PCN,'0','') = '' 
        THEN NULL 
        ELSE A.NU_CPF_PCN 
    END AS "CPF_PAC",
    -- CNS: mesma lógica
    CASE 
    	WHEN TRIM(A.CO_APA_CNSPCT) IS NULL 
         	OR REGEXP_REPLACE(A.CO_APA_CNSPCT,'0','') = '' 
    	THEN P.CO_PA_CNSPAC
    	ELSE A.CO_APA_CNSPCT
	END AS "CNS_PAC",
    P.CO_PA_PROC_ID AS "COD_SIGTAP_PROCEDIMENTO",
    P.CO_PA_CBOCOD AS "CBO",
    UF.SG_UF AS "UF_DESC_ATEND",
    P.NU_MUN_HOSP 	 AS "IBGE_ATEND",
    P.CO_CNES  AS "CNES_ATEND",
    -- Tratamento seguro para CO_PA_MVM (YYYYMM)
    CASE 
        WHEN LENGTH(P.DT_CMPT) = 6 
        THEN TO_CHAR(TO_DATE(P.DT_CMPT , 'YYYYMM'), 'MM/YYYY') 
    END AS "DT_CMP_FORMATADA",
    -- Tratamento seguro para datas (YYYYMMDD)
    CASE 
        WHEN LENGTH(A.CO_APA_DTSOL) = 8 
        THEN TO_CHAR(TO_DATE(A.CO_APA_DTSOL , 'YYYYMMDD'),'DD/MM/YYYY') 
    END AS "DATA_SOLICITACAO",
    CASE 
        WHEN LENGTH(A.CO_APA_DTAUT) = 8 
        THEN TO_CHAR(TO_DATE(A.CO_APA_DTAUT , 'YYYYMMDD'),'DD/MM/YYYY') 
    END AS "DATA_AUTORIZACAO",
    CASE 
        WHEN LENGTH(A.CO_APA_DTINIC) = 8 
        THEN TO_CHAR(TO_DATE(A.CO_APA_DTINIC,'YYYYMMDD'),'DD/MM/YYYY') 
    END AS "DATA_INICIO", 
    CASE 
        WHEN LENGTH(A.CO_APA_DTFIM) = 8 
        THEN TO_CHAR(TO_DATE(A.CO_APA_DTFIM ,'YYYYMMDD'),'DD/MM/YYYY') 
    END AS "DATA_FINAL", 
    A.CO_APA_NUM
FROM 
    AIH.TB_REDUZ P
    LEFT JOIN DBGERAL.TB_UF UF 
        ON UF.CO_UF_IBGE = SUBSTR(P. P.NU_MUN_HOSP, 1, 2)
WHERE
   P.DT_CMPT(202407,202408,202409,202410,202411,202412, 
   					202501,202502,202503,202504,202505,202506)
